{"command": "for id in ba0ec392a6ff484e 0e34493cdaf34a39; do
  echo "=== MSG $id ==="
  gws gmail users messages get --params "{\"userId\": \"me\", \"id\": \"$id\", \"format\": \"full\"}" 2>/dev/null | python3 -c "
import sys, json, base64
d = json.load(sys.stdin)
for h in d.get('payload',{}).get('headers',[]):
    print(h['name'],':',h['value'])
# Try to get body
def get_body(payload):
    if 'body' in payload and payload['body'].get('data'):
        return base64.urlsafe_b64decode(payload['body']['data']).decode('utf-8', errors='replace')
    parts = payload.get('parts',[])
    for p in parts:
        b = get_body(p)
        if b:
            return b
    return ''
body = get_body(d.get('payload',{}))
print('---BODY---')
print(body[:3000])
" 2>&1
  echo
done", "timeout": 30}

